+    fn handle_visual_key(&mut self, key: UiKey) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => self.clear_visual_selection(),
+            UiKey::Char('h') | UiKey::Left => self.move_visual_cursor(0, -1),
+            UiKey::Char('j') | UiKey::Down => self.move_visual_cursor(1, 0),
+            UiKey::Char('k') | UiKey::Up => self.move_visual_cursor(-1, 0),
+            UiKey::Char('l') | UiKey::Right => self.move_visual_cursor(0, 1),
+            UiKey::Char('v') => self.start_visual_selection(VisualSelectionKind::Character),
+            UiKey::Char('V') => self.start_visual_selection(VisualSelectionKind::Line),
+            UiKey::CtrlV => self.start_visual_selection(VisualSelectionKind::Block),
+            UiKey::Char('y') => self.yank_visual_selection(false),
+            UiKey::Char('Y') => self.yank_visual_selection(true),
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn start_visual_selection(&mut self, kind: VisualSelectionKind) {
+        let pane = self.focus;
+        let row = self.current_visual_row(pane);
+        let point = SelectionPoint { row, column: 0 };
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: point,
+            cursor: point,
+        });
+        self.pending = None;
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn current_visual_row(&self, pane: PaneFocus) -> usize {
+        match pane {
+            PaneFocus::Left => self
+                .control_selected
+                .min(self.left_selectable_lines().len().saturating_sub(1)),
+            PaneFocus::Right => self.right_visual_rows.get().saturating_sub(1),
+        }
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize) {
+        let Some(mut selection) = self.visual_selection else {
+            return;
+        };
+        let max_row = self.visual_row_count(selection.pane).saturating_sub(1);
+        let max_column = self.visual_column_count(selection.pane).saturating_sub(1);
+        selection.cursor.row = add_signed(selection.cursor.row, row_delta).min(max_row);
+        selection.cursor.column = add_signed(selection.cursor.column, column_delta).min(max_column);
+        self.visual_selection = Some(selection);
+    }
+
+    fn yank_visual_selection(&mut self, force_linewise: bool) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        self.pending_copy.set(Some(VisualCopyRequest {
+            selection,
+            force_linewise,
+        }));
+        self.clear_visual_selection();
+    }
+
+    fn yank_focused_line(&mut self) {
+        let pane = self.focus;
+        let point = SelectionPoint {
+            row: self.current_visual_row(pane),
+            column: 0,
+        };
+        self.pending_copy.set(Some(VisualCopyRequest {
+            selection: VisualSelection {
+                pane,
+                kind: VisualSelectionKind::Line,
+                anchor: point,
+                cursor: point,
+            },
+            force_linewise: true,
+        }));
+    }
+
+    fn visual_row_count(&self, pane: PaneFocus) -> usize {
+        match pane {
+            PaneFocus::Left => self.left_selectable_lines().len().max(1),
+            PaneFocus::Right => self.right_visual_rows.get().max(1),
+        }
+    }
+
+    fn visual_column_count(&self, pane: PaneFocus) -> usize {
+        let width = match pane {
+            PaneFocus::Left => self.layout().left_width,
+            PaneFocus::Right => self.layout().right_width,
+        };
+        usize::from(width.saturating_sub(2).max(1))
+    }
+
+    fn apply_visual_selection(&self, buffer: &mut Buffer, right_content: &str) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let Some(inner) = self.pane_inner_rect(selection.pane) else {
+            return;
+        };
+        let rows = self.selection_rows(selection.pane, right_content);
+        for (row, start, end) in selection_ranges(&rows, selection, false, Some(inner.width)) {
+            if row >= usize::from(inner.height) {
+                continue;
+            }
+            let start = start.min(usize::from(inner.width));
+            let end = end.min(usize::from(inner.width));
+            for column in start..end {
+                buffer
+                    .get_mut(inner.x + column as u16, inner.y + row as u16)
+                    .modifier
+                    .insert(Modifier::REVERSED);
+            }
+        }
+    }
+
+    fn copy_request_text(&self, request: VisualCopyRequest, right_content: &str) -> String {
+        let rows = self.selection_rows(request.selection.pane, right_content);
+        selected_text(&rows, request.selection, request.force_linewise)
+    }
+
+    fn selection_rows(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self.left_selectable_lines(),
+            PaneFocus::Right => self.right_selectable_lines(right_content),
+        }
+    }
+
+    fn left_selectable_lines(&self) -> Vec<String> {
+        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+        let mut lines = vec![truncate_to_width(
+            if self.control_selected == 0 {
+                "> work-leaf  command"
+            } else {
+                "  work-leaf  command"
+            },
+            inner_width,
+        )];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            lines.push(compact_agent_row(
+                agent,
+                self.control_selected == visible_position + 1,
+                inner_width,
+            ));
+            if !agent.modified_files.is_empty() {
+                lines.push(truncate_to_width(
+                    &format!(
+                        "    files: {}",
+                        agent
+                            .modified_files
+                            .iter()
+                            .map(|path| path.display().to_string())
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ),
+                    inner_width,
+                ));
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    lines.push(truncate_to_width(
+                        &format!(
+                            "    {label}: {}",
+                            agents
+                                .iter()
+                                .map(AgentId::as_str)
+                                .collect::<Vec<_>>()
+                                .join(", ")
+                        ),
+                        inner_width,
+                    ));
+                }
+            }
+        }
+        if lines.is_empty() {
+            lines.push(String::new());
+        }
+        lines
+    }
+
+    fn right_selectable_lines(&self, right_content: &str) -> Vec<String> {
+        let (inner_width, _) = self.right_inner_size();
+        wrapped_rows(right_content, inner_width)
+    }
+
+    fn pane_inner_rect(&self, pane: PaneFocus) -> Option<Rect> {
+        let layout = self.layout();
+        let body_height = self.height.saturating_sub(1);
+        let pane_rect = match pane {
+            PaneFocus::Left if self.left_visible && layout.left_width > 0 => {
+                Rect::new(0, 0, layout.left_width, body_height)
+            }
+            PaneFocus::Left => return None,
+            PaneFocus::Right => Rect::new(
+                if self.left_visible { layout.left_width } else { 0 },
+                0,
+                layout.right_width,
+                body_height,
+            ),
+        };
+        let width = pane_rect.width.saturating_sub(2);
+        let height = pane_rect.height.saturating_sub(2);
+        (width > 0 && height > 0).then(|| {
+            Rect::new(
+                pane_rect.x.saturating_add(1),
+                pane_rect.y.saturating_add(1),
+                width,
+                height,
+            )
+        })
+    }

